private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (bb == null || sb == null) {
        throw new IllegalArgumentException("ByteBuffer and StringBuilder must not be null");
    }
    if (i < 0 || i > bb.limit()) {
        throw new IllegalArgumentException("Index i is out of bounds");
    }

    bb.position(i);
    while (bb.hasRemaining()) {
        byte b = bb.get();
        if ((b & 0x80) == 0) {
            // Single-byte character
            sb.append((char) b);
        } else if ((b & 0xE0) == 0xC0) {
            // Two-byte character
            if (!bb.hasRemaining()) {
                throw new IllegalArgumentException("Incomplete UTF-8 sequence");
            }
            byte b2 = bb.get();
            if ((b2 & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            sb.append((char) (((b & 0x1F) << 6) | (b2 & 0x3F)));
        } else if ((b & 0xF0) == 0xE0) {
            // Three-byte character
            if (bb.remaining() < 2) {
                throw new IllegalArgumentException("Incomplete UTF-8 sequence");
            }
            byte b2 = bb.get();
            byte b3 = bb.get();
            if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            sb.append((char) (((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F)));
        } else if ((b & 0xF8) == 0xF0) {
            // Four-byte character
            if (bb.remaining() < 3) {
                throw new IllegalArgumentException("Incomplete UTF-8 sequence");
            }
            byte b2 = bb.get();
            byte b3 = bb.get();
            byte b4 = bb.get();
            if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80 || (b4 & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            int codePoint = ((b & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F);
            sb.append(Character.toChars(codePoint));
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        }
    }
    return bb.position();
}

