        throw new IllegalArgumentException("Target graph cannot be null");
    }
    if (resultMap == null) {
        throw new IllegalArgumentException("Result map cannot be null");
    }
    if (resultMap.size() < 2) {
        throw new IllegalArgumentException("Result map must contain at least two vertices to form a bipartite graph");
    }

    // Split the vertices into two sets for bipartition
    List<V> set1 = new ArrayList<>();
    List<V> set2 = new ArrayList<>();
    int index = 0;
    for (V vertex : resultMap.values()) {
        if (index % 2 == 0) {
            set1.add(vertex);
        } else {
            set2.add(vertex);
        }
        index++;
    }

    // Add edges between all vertices in set1 and set2
