public long readLong(final int offset){
    if (offset < 0) {
        throw new IllegalArgumentException("Offset cannot be negative");
    }
    if (offset + 8 > this.b.length) {
        throw new IllegalArgumentException("Offset is out of bounds for reading a long value");
    }
    return ((long)this.b[offset] & 0xFF) << 56
         | ((long)this.b[offset + 1] & 0xFF) << 48
         | ((long)this.b[offset + 2] & 0xFF) << 40
         | ((long)this.b[offset + 3] & 0xFF) << 32
         | ((long)this.b[offset + 4] & 0xFF) << 24
         | ((long)this.b[offset + 5] & 0xFF) << 16
         | ((long)this.b[offset + 6] & 0xFF) << 8
         | ((long)this.b[offset + 7] & 0xFF);
}

