public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= length) {
                throw new Exception("Invalid escape sequence at end of string");
            }
            char nextChar = str.charAt(i + 1);
            switch (nextChar) {
                case 'b':
                    result.append('\b');
                    break;
                case 't':
                    result.append('\t');
                    break;
                case 'n':
                    result.append('\n');
                    break;
                case 'f':
                    result.append('\f');
                    break;
                case 'r':
                    result.append('\r');
                    break;
                case '"':
                    result.append('"');
                    break;
                case '\'':
                    result.append('\'');
                    break;
                case '\\':
                    result.append('\\');
                    break;
                case 'u':
                    if (i + 5 >= length) {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int codePoint = Integer.parseInt(hex, 16);
                        result.append((char) codePoint);
                        i += 5; // Skip the hex digits
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid Unicode escape sequence: " + hex);
                    }
                    break;
                default:
                    throw new Exception("Invalid escape sequence: \\" + nextChar);
            }
            i++; // Skip the next character as it is part of the escape sequence
        } else {
            result.append(c);
        }
    }
    return result.toString();
}

