private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate cannot be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("Start node cannot be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("Stop node cannot be null");
    }
    if (dir < 0 || dir > 1) {
        throw new IllegalArgumentException("Direction must be 0 or 1");
    }

    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);

    while (!circulator.getNode().equals(stop)) {
        if (predicate.test(circulator.getNode())) {
            return circulator;
        }
        circulator.advance();
    }

    return circulator;
}

