protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, Collections.emptyList(), 0.0);
    }

    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = null;
    V currentVertex = null;
    Map<V, List<E>> adjacencyList = new HashMap<>();

    // Build adjacency list from the graph
    for (E edge : graph.edgeSet()) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        adjacencyList.computeIfAbsent(source, k -> new ArrayList<>()).add(edge);
        adjacencyList.computeIfAbsent(target, k -> new ArrayList<>()).add(edge);
    }

    // Find a starting vertex
    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (adjacencyList.get(source).size() % 2 != 0) {
            startVertex = source;
            break;
        } else if (adjacencyList.get(target).size() % 2 != 0) {
            startVertex = target;
            break;
        }
    }

    if (startVertex == null) {
        startVertex = graph.getEdgeSource(edgeList.get(0));
    }

    currentVertex = startVertex;
    List<E> pathEdges = new ArrayList<>();
    Set<E> visitedEdges = new HashSet<>();

    // Hierholzer's algorithm to find Eulerian circuit/path
    while (!edgeList.isEmpty()) {
        if (adjacencyList.get(currentVertex).isEmpty()) {
            pathEdges.add(edgeList.remove(0));
            visitedEdges.add(pathEdges.get(pathEdges.size() - 1));
            currentVertex = graph.getEdgeTarget(pathEdges.get(pathEdges.size() - 1));
        } else {
            E nextEdge = adjacencyList.get(currentVertex).remove(0);
            edgeList.remove(nextEdge);
            visitedEdges.add(nextEdge);
            pathEdges.add(nextEdge);
            currentVertex = graph.getEdgeTarget(nextEdge);
        }
    }

    List<V> pathVertices = new ArrayList<>();
    for (E edge : pathEdges) {
        if (pathVertices.isEmpty() || !pathVertices.get(pathVertices.size() - 1).equals(graph.getEdgeSource(edge))) {
            pathVertices.add(graph.getEdgeSource(edge));
        }
        pathVertices.add(graph.getEdgeTarget(edge));
    }

