public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("Buffer cannot be null");
    }
    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("nameStart is out of buffer bounds");
    }

    // Find the end of the first word
    int end = nameStart;
    while (end < buf.length() && Character.isLetterOrDigit(buf.charAt(end))) {
        end++;
    }

    if (end == nameStart) {
        // No valid word found to abbreviate
        return;
    }

    // Append the first character of the word
    buf.append(buf.charAt(nameStart)).append('.');

    // Move the start to the end of the current word
    nameStart = end;

    // Find and abbreviate subsequent words
    while (nameStart < buf.length()) {
        // Skip non-letter characters
        while (nameStart < buf.length() && !Character.isLetterOrDigit(buf.charAt(nameStart))) {
            nameStart++;
        }

        if (nameStart >= buf.length()) {
            break;
        }

        // Find the end of the next word
        end = nameStart;
        while (end < buf.length() && Character.isLetterOrDigit(buf.charAt(end))) {
            end++;
        }

        // Append the first character of the word followed by a dot
        buf.append(buf.charAt(nameStart)).append('.');

        // Move the start to the end of the current word
        nameStart = end;
    }

    // Remove the last dot if present
    if (buf.charAt(buf.length() - 1) == '.') {
        buf.setLength(buf.length() - 1);
    }
}

