private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    if (descriptor.isEmpty()) {
        return; // No types to pop if descriptor is empty
    }

    int index = 0;
    if (descriptor.charAt(0) == '(') {
        // Method descriptor, find the end of the argument types
        index = descriptor.indexOf(')');
        if (index == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        index++; // Move past the ')'
    }

    while (index < descriptor.length()) {
        char c = descriptor.charAt(index++);
        switch (c) {
            case 'B': // byte
            case 'C': // char
            case 'D': // double
            case 'F': // float
            case 'I': // int
            case 'J': // long
            case 'S': // short
            case 'Z': // boolean
                // These are all single-word types
                popSingleWordType();
                break;
            case 'L':
                // Object type, skip to the end of the class name
                while (index < descriptor.length() && descriptor.charAt(index) != ';') {
                    index++;
                }
                if (index == descriptor.length()) {
                    throw new IllegalArgumentException("Invalid object type descriptor: missing ';'");
                }
                index++; // Move past the ';'
                popSingleWordType();
                break;
            case '[':
                // Array type, skip to the end of the array descriptor
                while (index < descriptor.length() && descriptor.charAt(index) == '[') {
                    index++;
                }
                if (index == descriptor.length()) {
                    throw new IllegalArgumentException("Invalid array descriptor: missing element type");
                }
                // The element type is a single-word type or an object type
                if (descriptor.charAt(index) == 'L') {
                    index++; // Move past the 'L'
                    while (index < descriptor.length() && descriptor.charAt(index) != ';') {
                        index++;
                    }
                    if (index == descriptor.length()) {
                        throw new IllegalArgumentException("Invalid object type descriptor in array: missing ';'");
                    }
                    index++; // Move past the ';'
                } else {
                    index++; // Move past the single-word type character
                }
                popSingleWordType();
                break;
            default:
                throw new IllegalArgumentException("Invalid descriptor character: " + c);
        }
    }
}

